// === Tab: pine ===
let pineId = 0
function pine() {
	const branches = []
	const states = [{
		x: 0,
		y: 0,
		z: 0,
		scale: 1,
		theta: 0,
		phi: 0,
	}]
	const getState = () => states[states.length - 1]
	const pushState = () => states.push({ ...getState() })
	const popState = () => states.pop()

	const branchHeight = 50

	const moveToBranchEnd = () => {
		const newLoc = createVector(getState().x, getState().y, getState().z)
			.add(p5.Vector.fromAngles(getState().theta, getState().phi, getState().scale * branchHeight))
		getState().x = newLoc.x
		getState().y = newLoc.y
		getState().z = newLoc.z
	}

	const addBranch	= (depth = 0) => {
		if (depth > 10) return
		if (getState().scale < 0.1) return

		// Up
		pushState()
		getState().theta += random(-0.05, 0.05) * PI
		getState().phi += random(-0.05, 0.05) * PI

		branches.push({ ...getState() })

		getState().scale *= random(0.8, 1)
		moveToBranchEnd()
		addBranch(depth + 1)
		popState()

		// Sides
		if (depth === 0) return
		const numSides = round(random(1, map(depth, 0, 5, 4, 1, true)))
		const angleJitter = random() * PI
		for (let i = 0; i < numSides; i++) {
			pushState()
			//getState().theta += random(0.35, 0.45) * PI
			getState().theta += random(0.3, 0.35) * PI
			getState().phi += angleJitter + (i / numSides) * TWO_PI
			getState().scale *= 0.65
			addBranch(depth + 1)
			//moveToBranchEnd()
			popState()
		}
	}
	addBranch()

	return new p5.Geometry(1, 1, function() {
		this.gid = `pine|${++pineId}`
		for (const branch of branches) {
			const root = createVector(branch.x, branch.y, branch.z)
			const tip = root.copy()
				.add(p5.Vector.fromAngles(branch.theta, branch.phi, branch.scale * branchHeight))
			//const tangent = tip.copy().sub(root).normalize()
			//const up = createVector(0, -1, 0)
			//const normal = up.cross(tangent)
			const startIdx = this.vertices.length
			this.vertices.push(root)
			this.vertices.push(tip)
			this.faces.push([startIdx, startIdx + 1, startIdx])
			this.edges.push([startIdx, startIdx + 1])
		}
		//this.normalize()
	})
}

// === Tab: BlurAndFogRenderer ===
class BlurAndFogRenderer extends GaussianBlurRenderer {
	frag() {
    return BlurAndFogRenderer.frag
  }

	getUniforms() {
		return {
			...super.getUniforms(),
			t: millis(),
		}
	}
}

BlurAndFogRenderer.frag = `
precision highp float;
varying highp vec2 vVertTexCoord;
uniform sampler2D uImg;
uniform sampler2D uDepth;
uniform vec2 uSize;
uniform float uIntensity;
uniform float uDof;
uniform float maxBlur;
uniform int uNumSamples;
uniform float uTargetZ;
uniform float uNear;
uniform float uFar;
uniform int uDirection;
uniform float t;
#define s ${0.5/3}
const int MAX_NUM_SAMPLES = 50;

// Noise functions
// https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
float rand(float n) {
	return fract(sin(n) * 43758.5453123);
}
float rand(vec2 n) { 
	return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}
float noise(float p) {
	float fl = floor(p);
	float fc = fract(p);
	return mix(rand(fl), rand(fl + 1.0), fc);
}
float noise(vec2 n) {
	const vec2 d = vec2(0.0, 1.0);
	vec2 b = floor(n);
	vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
	return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
}

float map(float value, float min1, float max1, float min2, float max2) {
  return min2 + (value - min1) * (max2 - min2) / (max1 - min1);
}
float depthToZ(float depth) {
  float depthNormalized = 2.0 * depth - 1.0;
  return 2.0 * uNear * uFar / (uFar + uNear - depthNormalized * (uFar - uNear));
}
float calcBlur(float z, float pixelScale) {
  return clamp(abs(z - uTargetZ) - uDof / 2., 0.0, 0.3*pixelScale);
}
float fogAtCoord(vec2 coord, float depth) {
	if (uDirection == 0) return 0.;
	float off = coord.x * 5. + coord.y * 2.5;
	float mixAmt = map(depth, 200., 2000., 0., 1.)
		+ sin(sqrt(depth) * 0.1 + off + t * 0.004) * 0.05
		+ sin(sqrt(depth) * 0.8 + off + t * 0.007) * 0.001;

	mixAmt = clamp(mixAmt, 0., 1.);

	// snow
	for (float z = 100.; z < 1000.; z += (Math.max(0.001, Math.abs(300.)) || 1)) {
		float snowAmt = smoothstep(z - 0.1, z, depth);
		mixAmt += snowAmt * smoothstep(
			0.96,
			0.97,
			noise((coord + t * 0.4/(0.8*z))*0.12*z)
		);
	}

	mixAmt = clamp(mixAmt, 0., 1.);

	return mixAmt;
}
void main() {
  float total = 1.0;
  float origZ = depthToZ(texture2D(uDepth, vVertTexCoord).x);
  vec4 color = texture2D(uImg, vVertTexCoord);
  if (abs(origZ - uTargetZ) > uDof / 2.) {
    float pixelScale = max(uSize.x, uSize.y);
    float blurAmt = calcBlur(origZ, pixelScale);
    for (int i = 0; i < MAX_NUM_SAMPLES; i++) {
      if (i >= uNumSamples) break;
      float t = (float(i) / float(uNumSamples - 1));
      float radius = (t * 2. - 1.);
      float distAway = radius * uIntensity * blurAmt;
      vec2 offset = (uDirection == 0 ? vec2(1.,0.) : vec2(0.,1.)) * distAway / pixelScale;
      float z = depthToZ(texture2D(uDepth, vVertTexCoord + offset).x);
      float sampleBlur = calcBlur(z, pixelScale);
      float t2 = distAway / (sampleBlur * uIntensity);
      float weight = ${1/Math.sqrt(2*Math.PI)} / s * exp(-0.5*pow(t2/s,2.));
      vec4 sample = texture2D(uImg, vVertTexCoord + offset);
      color += weight * sample;
      total += weight;
    }
  }
  color /= total;
  gl_FragColor = mix(
		color,
		vec4(1., 1., 1., 1.),
		fogAtCoord(vVertTexCoord, origZ)
	);
}
`

// === Tab: mySketch ===
let renderer
const trees = []

function setup() {
	createCanvas(600, 600, WEBGL)
	pixelDensity(2)
	renderer = new BlurAndFogRenderer(window)
	renderer.setSamples(30)
	renderer.setDof(100)
	renderer.setIntensity(0.05)
	for (let i = 0; i < 30; i++) {
		const x = random(-400, 400)
		const z = random(-1400, 200)
		trees.push({
			x,
			z,
			noiseOffset: random(1) + 100*noise(x*0.2, z*0.2),
			geom: pine(),
		})
	}
	let minTree
	let minTreeDist = Infinity
	for (const tree of trees) {
		const distToCenter = Math.hypot(tree.x, tree.z)
		if (distToCenter < minTreeDist) {
			minTreeDist = distToCenter
			minTree = tree
		}
	}
	minTree.focus = true
	noiseDetail(4, 0.35)
}

function draw() {
	clear()
	const t = millis()

	renderer.draw(() => {
		clear()
		background(255)
		push()
		rotateX(-PI*0.15)
		fill(0)
		stroke('#37573c')
		strokeWeight(5)
		for (const tree of trees) {
			push()
			translate(tree.x, height * 0.2, tree.z)
			rotateZ(noise(t*0.00065, tree.x*0.008, tree.z*0.008) * PI*0.02)
			model(tree.geom)
			if (tree.focus) {
				translate(0, -200, 0)
				renderer.focusHere()
			}
			pop()
		}
		pop()
	})
}
